package dev.astralreach.hytale;
import com.hypixel.hytale.codec.*;
import com.hypixel.hytale.codec.builder.BuilderCodec;
import com.hypixel.hytale.component.*;
import com.hypixel.hytale.protocol.packets.interface_.*;
import com.hypixel.hytale.server.core.entity.entities.Player;
import com.hypixel.hytale.server.core.entity.entities.player.pages.InteractiveCustomUIPage;
import com.hypixel.hytale.server.core.ui.builder.*;
import com.hypixel.hytale.server.core.universe.PlayerRef;
import com.hypixel.hytale.server.core.universe.world.storage.EntityStore;
import java.util.*;

/** Native station selection/deployment and on-foot crew controls; no client travel/payment authority. */
final class StationPage extends InteractiveCustomUIPage<StationPage.Action>{
 static final class Action{String action="",name="",nonce="";static final BuilderCodec<Action>CODEC=BuilderCodec.builder(Action.class,Action::new).append(new KeyedCodec<>("Action",Codec.STRING),(a,v)->a.action=v,a->a.action).add().append(new KeyedCodec<>("@Name",Codec.STRING),(a,v)->a.name=v,a->a.name).add().append(new KeyedCodec<>("Nonce",Codec.STRING),(a,v)->a.nonce=v,a->a.nonce).add().build();}
 private UUID selected;private int page;private boolean onsite,dismissed;private long refreshAt;private List<UUID>rows=List.of();private final String nonce=UUID.randomUUID().toString();
 StationPage(PlayerRef p,UUID selected,int page){super(p,CustomPageLifetime.CanDismiss,Action.CODEC);this.selected=selected;this.page=Math.max(0,page);}
 static void open(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p){show(s,r,p,p.getUuid(),0);}
 private static void show(Store<EntityStore>s,Ref<EntityStore>r,PlayerRef p,UUID selected,int page){StationService.paid(s,r);OrbitalMapPage.close(p);s.getComponent(r,Player.getComponentType()).getPageManager().openCustomPage(r,s,new StationPage(p,selected,page));}
 private List<UUID>choices(Store<EntityStore>s,Ref<EntityStore>r){var f=StationService.paid(s,r);if(f.stationOwner!=null){var st=StationService.data(s).stations.get(f.stationOwner);return st==null?List.of():List.copyOf(st.crew.keySet());}var list=new ArrayList<UUID>();list.add(playerRef.getUuid());for(var st:StationService.available(s,playerRef.getUuid()))if(!st.owner.equals(playerRef.getUuid()))list.add(st.owner);return List.copyOf(list);}
 private void labels(Store<EntityStore>s,Ref<EntityStore>r,UICommandBuilder c){var f=StationService.paid(s,r);var st=StationService.data(s).stations.get(selected);var player=s.getComponent(r,Player.getComponentType());int cores=StationService.cores(s,r),tier=ExpeditionSuit.tier(s,r);double oxygen=OxygenCanisters.total(player.getInventory().getCombinedStorageHotbarBackpack());boolean owner=onsite&&st!=null&&st.owner.equals(playerRef.getUuid());
  c.set("#ListHeading.Text",onsite?"INVITED BUILDERS":"STATIONS");c.set("#Title.Text",st==null?"YOUR STATION":st.title());c.set("#Status.Text",onsite?"Docked · airlock "+String.format(java.util.Locale.ROOT,"%02d",f.stationPort+1)+"":st!=null?(st.shellVersion<2?"Concourse assembling · reserve protected":st.moorings.size()+" / 9 airlocks occupied"):cores>0?(tier>=1&&oxygen>=240?"Core carried · ready to deploy":"Core carried · check readiness"):"Craft and carry a Station Core");
  c.set("#CorePanel.Visible",true);c.set("#CoreHeading.Text",onsite?"STATION CORE":"REQUIRED ITEM");c.set("#CoreColumn.Text",st==null?"Required":"Installed");c.set("#CoreItem.ItemId","AR_StationCore");c.set("#CoreRequired.Text","1");c.set("#CoreCarried.Text",Integer.toString(cores));c.set("#CoreLabel.Text",st==null?"Station Core":"Permanent core");
  c.set("#InfoHeading.Text",onsite?"YOUR BUILD PLOT":"ABOUT THE STARTER STATION");c.set("#Info0.Text","9 external docking airlocks");c.set("#Info1.Text","193 × 193 persistent build plot");c.set("#Info2.Text",st==null?"Invite up to 8 builders":st.crew.size()+" / 8 invited builders");c.set("#Info3.Text","Open space · 3 starter platforms");
  c.set("#Suit.Text",tier>=1?"Survey suit equipped":"Complete Survey suit required");c.set("#Oxygen.Text","Oxygen · "+NativeUi.duration(oxygen));c.set("#Reserve.Text",NativeUi.number(f.trip.returnUnits())+" return fuel protected");
  c.set("#Deploy.Visible",!onsite&&st==null&&selected.equals(playerRef.getUuid()));c.set("#Deploy.Disabled",cores<1||tier<1||oxygen<240);c.set("#Dock.Visible",!onsite&&st!=null);c.set("#Dock.Disabled",st==null||st.shellVersion<2||tier<1||oxygen<240);c.set("#Systems.Visible",onsite);c.set("#Undock.Visible",onsite);c.set("#Home.Visible",onsite);c.set("#Close.Text",onsite?"Close":"Destinations");
  c.set("#InviteBox.Visible",owner);c.set("#Empty.Visible",onsite&&rows.isEmpty());c.set("#Empty.Text","No invited builders yet");c.set("#Page.Text",(page+1)+" / "+Math.max(1,(rows.size()+5)/6));c.set("#Previous.Disabled",page==0);c.set("#Next.Disabled",(page+1)*6>=rows.size());
  c.set("#Hint.Text",onsite?"Invited builders can edit this plot. Core and arrival square stay protected.":"Docking keeps your paid return reserve. Bring filled oxygen canisters.");
  for(int i=0;i<6;i++){int at=page*6+i;String id="#Row"+i;boolean visible=at<rows.size();c.set(id+".Visible",visible);if(!visible)continue;var uuid=rows.get(at);var station=StationService.data(s).stations.get(uuid);c.set(id+" #Chosen.Visible",!onsite&&uuid.equals(selected));c.set(id+" #Icon.Visible",!onsite);if(!onsite)c.set(id+" #Icon.ItemId","AR_StationCore");c.set(id+" #Name.Text",onsite?st.crew.get(uuid):uuid.equals(playerRef.getUuid())?"Your station":station.title());c.set(id+" #Note.Text",onsite?"Builder":station==null?"Not deployed":uuid.equals(playerRef.getUuid())?"Owned":"Invited");c.set(id+" #Remove.Visible",owner);}
 }
 @Override public void build(Ref<EntityStore>r,UICommandBuilder c,UIEventBuilder e,Store<EntityStore>s){var f=StationService.paid(s,r);onsite=f.stationOwner!=null;if(onsite)selected=f.stationOwner;rows=choices(s,r);if(!onsite&&!rows.contains(selected))selected=playerRef.getUuid();page=Math.min(page,Math.max(0,(rows.size()-1)/6));c.append("Pages/AstralReach/Station.ui");labels(s,r,c);NativeUi.cue(s,playerRef);
  for(String action:List.of("Close","Systems","Deploy","Dock","Undock","Home","Previous","Next"))bind(e,"#"+action,action);
  e.addEventBinding(CustomUIEventBindingType.Activating,"#Invite",EventData.of("Action","Invite").append("Nonce",nonce).append("@Name","#GuestName.Value"),false);
  for(int i=0;i<6;i++){int at=page*6+i;if(at>=rows.size())continue;if(!onsite)bind(e,"#Row"+i,"Pick:"+rows.get(at));else bind(e,"#Row"+i+" #Remove","Remove:"+rows.get(at));}
 }
 private void bind(UIEventBuilder e,String id,String action){e.addEventBinding(CustomUIEventBindingType.Activating,id,EventData.of("Action",action).append("Nonce",nonce),false);}
 void finish(){close();}
 void refresh(Store<EntityStore>s,Ref<EntityStore>r){if(dismissed||System.nanoTime()-refreshAt<1_000_000_000L)return;refreshAt=System.nanoTime();try{var f=StationService.paid(s,r);if(onsite!=(f.stationOwner!=null)||!rows.equals(choices(s,r))){show(s,r,playerRef,selected,page);return;}var c=new UICommandBuilder();labels(s,r,c);sendUpdate(c,false);}catch(IllegalArgumentException ex){close();}}
 @Override public void handleDataEvent(Ref<EntityStore>r,Store<EntityStore>s,Action a){s.getExternalData().getWorld().execute(()->{if(dismissed||!nonce.equals(a.nonce)||!r.isValid()||r.getStore()!=s||s.getComponent(r,Player.getComponentType()).getPageManager().getCustomPage()!=this)return;try{StationService.paid(s,r);String action=a.action;if(action.equals("Close")){if(onsite)close();else OrbitalMapPage.open(s,r,playerRef);return;}if(action.equals("Previous")||action.equals("Next")){show(s,r,playerRef,selected,page+(action.equals("Next")?1:-1));return;}if(action.startsWith("Pick:")){var id=UUID.fromString(action.substring(5));if(!onsite&&rows.contains(id))show(s,r,playerRef,id,page);return;}if(action.startsWith("Remove:")){StationService.revoke(s,r,playerRef,UUID.fromString(action.substring(7)));show(s,r,playerRef,selected,page);return;}switch(action){case "Systems"->StationSystemsPage.open(s,r,playerRef,null);case "Invite"->{StationService.invite(s,r,playerRef,a.name);show(s,r,playerRef,selected,page);}case "Deploy"->StationService.deploy(s,r,playerRef);case "Dock"->StationService.dock(s,r,playerRef,selected);case "Undock"->StationService.undock(s,r,playerRef);case "Home"->{close();RocketService.returnHome(s,r,playerRef);}default->{}}}catch(IllegalArgumentException ex){AstralReachPlugin.message(playerRef,ex.getMessage());}});}
 @Override public void onDismiss(Ref<EntityStore>r,Store<EntityStore>s){dismissed=true;}
}
